"use client"

import {
  ColumnDef,
  flexRender,
  getCoreRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  SortingState,
  useReactTable,
} from "@tanstack/react-table"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import React from "react"
import { DataTablePagination } from "@/components/datatable/data-table-pagination"
import { SkeletonTable } from "@/components/datatable/skeleton-table"
import { ArrowDown, ArrowUp, ArrowUpDown, Minus } from "lucide-react"
import { cn } from "@/lib/utils"

type ExtendedColumnDef<TData, TValue> = ColumnDef<TData, TValue> & {
  sortable?: boolean
}

interface DataTableProps<TData, TValue> {
  columns: ExtendedColumnDef<TData, TValue>[]
  data: TData[]
  pagination?: {
    pageSizeOptions?: number[]
    initialPageSize?: number
    initialPageIndex?: number
    onPaginationChange?: (pagination: { pageIndex: number; pageSize: number }) => void
    totalData?: number
  }
  loading?: boolean
  onSortingChange?: (sorting: SortingState) => void
  isSequenceNumber?: boolean
  isSelect?: boolean
  onSelect?: (selected: TData[]) => void
}

export function DataTable<TData, TValue>({
  columns,
  data,
  pagination,
  loading,
  onSortingChange,
  isSequenceNumber = true,
  isSelect = false,
  onSelect,
}: DataTableProps<TData, TValue>) {
  const calculatedPageCount =
    pagination?.totalData !== undefined && pagination.initialPageSize !== undefined
      ? Math.ceil(pagination.totalData / pagination.initialPageSize)
      : undefined

  const [sorting, setSorting] = React.useState<SortingState>([])
  const [isRender, setIsRender] = React.useState(false)
  const [trigerCheck, setTrigerCheck] = React.useState<TData[]>()

  const [paginationState, setPaginationState] = React.useState(
    pagination
      ? {
          pageIndex: pagination.initialPageIndex ? pagination.initialPageIndex - 1 : 0,
          pageSize: pagination.initialPageSize ?? 10,
        }
      : undefined
  )

  const table = useReactTable({
    data: data ?? [],
    columns: [],
    manualPagination: calculatedPageCount !== undefined,
    manualSorting: !!onSortingChange,
    enableMultiSort: false,
    pageCount: calculatedPageCount,
    initialState: {
      pagination: pagination
        ? {
            pageIndex: pagination.initialPageIndex ? pagination.initialPageIndex - 1 : 0,
            pageSize: pagination.initialPageSize ?? 10,
          }
        : undefined,
    },
    state: {
      pagination: paginationState,
      sorting,
    },
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: pagination ? getPaginationRowModel() : undefined,
    onPaginationChange: pagination
      ? (updater) => {
          setPaginationState((prev: any) => {
            const next = typeof updater === "function" ? updater(prev) : updater

            if (next.pageIndex === prev?.pageIndex && next.pageSize === prev.pageSize) {
              return prev
            }

            pagination.onPaginationChange?.({
              pageIndex: next.pageIndex + 1,
              pageSize: next.pageSize,
            })

            return next
          })
        }
      : undefined,
    onSortingChange: (updater) => {
      const newSorting = typeof updater === "function" ? updater(sorting) : updater
      setSorting(newSorting)
      onSortingChange?.(newSorting)
    },
    getSortedRowModel: getSortedRowModel(),
  })

  React.useEffect(() => {
    if (!pagination) return

    setPaginationState({
      pageIndex: pagination.initialPageIndex ? pagination.initialPageIndex - 1 : 0,
      pageSize: pagination.initialPageSize ?? 10,
    })
  }, [pagination?.initialPageIndex, pagination?.initialPageSize])

  const modifiedColumns = React.useMemo(() => {
    return [
      ...(isSelect
        ? [
            {
              id: "select",
              header: () => null,
              cell: ({ row }: any) => {
                const isSelected = row.getIsSelected()
                return (
                  <div className="flex items-center justify-center">
                    <div
                      className={cn(
                        "relative flex h-[18px] w-[18px] shrink-0 cursor-pointer items-center justify-center rounded-[5px] border-2 transition-all duration-200",
                        isSelected
                          ? "border-primary bg-primary shadow-sm shadow-primary/25"
                          : "border-muted-foreground/30 bg-background hover:border-primary/60 hover:bg-primary/5"
                      )}
                      onClick={() => {
                        row.toggleSelected(!isSelected)
                        const selected = table.getSelectedRowModel().rows.map((r) => r.original)
                        setTrigerCheck(selected)
                        onSelect?.(selected)
                      }}
                      role="checkbox"
                      aria-checked={isSelected}
                      aria-label="Select row"
                    >
                      <svg
                        className={cn(
                          "h-3 w-3 text-primary-foreground transition-all duration-200",
                          isSelected ? "scale-100 opacity-100" : "scale-0 opacity-0"
                        )}
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                        strokeWidth={3}
                      >
                        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                      </svg>
                    </div>
                  </div>
                )
              },
              enableSorting: false,
              enableHiding: false,
            },
          ]
        : []),
      ...(isSequenceNumber
        ? [
            {
              header: "No",
              accessorKey: "no",
              cell: ({ row }: any) => {
                const pageIndex = paginationState?.pageIndex ?? 0
                const pageSize = paginationState?.pageSize ?? 10
                const index = row.index + pageIndex * pageSize + 1
                return (
                  <span className="text-xs font-medium text-muted-foreground tabular-nums">
                    {index}
                  </span>
                )
              },
              enableSorting: false,
            },
          ]
        : []),
      ...columns.map((col: any) => ({
        ...col,
        columns: Array.isArray(col.columns)
          ? col.columns.map((child: any) => ({
              ...child,
              enableSorting: child.sortable ?? false,
            }))
          : undefined,
        enableSorting: col.sortable ?? false,
      })),
    ]
  }, [table, columns, isSelect, isSequenceNumber, paginationState])

  table.setOptions((prev) => ({
    ...prev,
    columns: modifiedColumns,
  }))

  React.useEffect(() => {
    setIsRender(true)
    if (!isSelect || !isRender || !table.getRowModel().rows?.length) return

    const selectedRows = table?.getSelectedRowModel()?.rows?.map((row) => row?.original) ?? []
    onSelect?.(selectedRows)
  }, [table, isSelect, trigerCheck, onSelect])

  if (loading)
    return <SkeletonTable table={table} columnCount={modifiedColumns.length} rowCount={12} />

  const indexEnd = table.getHeaderGroups().length - 1
  const selectedCount = table.getSelectedRowModel().rows.length
  const isAllSelected = table.getIsAllPageRowsSelected()
  const isSomeSelected = table.getIsSomePageRowsSelected()

  return (
    <div className="rounded-lg border bg-card shadow-sm overflow-hidden">
      {/* Selection indicator bar */}
      {isSelect && selectedCount > 0 && (
        <div className="flex items-center justify-between border-b bg-primary/5 px-4 py-2 transition-all duration-200">
          <div className="flex items-center gap-2">
            <div className="flex h-5 w-5 items-center justify-center rounded bg-primary">
              <svg 
                onClick={() => {
                table.toggleAllPageRowsSelected(false)
                setTrigerCheck([])
                onSelect?.([])
                }} 
                className="h-3 w-3 text-primary-foreground" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}
              >
                <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <span className="text-sm font-medium text-primary">
              {selectedCount} row{selectedCount > 1 ? "s" : ""} selected
            </span>
          </div>
          <button
            onClick={() => {
              table.toggleAllPageRowsSelected(false)
              setTrigerCheck([])
              onSelect?.([])
            }}
            className="text-xs font-medium text-muted-foreground hover:text-foreground transition-colors"
          >
            Clear selection
          </button>
        </div>
      )}

      <Table className="border-collapse">
        <TableHeader className="bg-muted/50">
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id} className="hover:bg-transparent border-b border-border/60">
              {headerGroup.headers.map((header) => (
                <TableHead
                  key={header.id}
                  colSpan={header?.colSpan}
                  className={cn(
                    "h-11",
                    header.id === "select" && isSelect
                      ? "w-[52px] bg-muted/50 sticky left-0 z-10"
                      : "border-border/40 border-r last:border-r-0"
                  )}
                >
                  {header.id === "select" && isSelect && data !== undefined ? (
                    <div className="flex items-center justify-center">
                      <div
                        className={cn(
                          "relative flex h-[18px] w-[18px] shrink-0 cursor-pointer items-center justify-center rounded-[5px] border-2 transition-all duration-200",
                          isAllSelected
                            ? "border-primary bg-primary shadow-sm shadow-primary/25"
                            : isSomeSelected
                              ? "border-primary bg-primary/10"
                              : "border-muted-foreground/30 bg-background hover:border-primary/60"
                        )}
                        onClick={() => {
                          table.toggleAllPageRowsSelected(!isAllSelected)
                          const selected = table.getSelectedRowModel().rows.map((row) => row.original)
                          setTrigerCheck(selected)
                          onSelect?.(selected)
                        }}
                        role="checkbox"
                        aria-checked={isAllSelected ? true : isSomeSelected ? "mixed" : false}
                        aria-label="Select all"
                      >
                        {isAllSelected ? (
                          <svg
                            className="h-3 w-3 text-primary-foreground transition-all duration-200 scale-100 opacity-100"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                            strokeWidth={3}
                          >
                            <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                          </svg>
                        ) : isSomeSelected ? (
                          <Minus className="h-3 w-3 text-primary transition-all duration-200" />
                        ) : null}
                      </div>
                    </div>
                  ) : header.isPlaceholder ? null : (
                    <div
                      className={cn(
                        "flex items-center gap-1 select-none",
                        header.column.getCanSort() && "cursor-pointer hover:text-foreground transition-colors",
                        headerGroup.depth === indexEnd ? "" : "justify-center"
                      )}
                      onClick={() => {
                        if (!header.column.getCanSort()) return

                        const isAsc = header.column.getIsSorted() === "asc"
                        const newSorting = [{ id: header.id, desc: isAsc }]
                        setSorting(newSorting)
                        onSortingChange?.(newSorting)
                      }}
                    >
                      <span className="text-xs font-semibold uppercase tracking-wider">
                        {flexRender(header.column.columnDef.header, header.getContext())}
                      </span>

                      {header.column.getCanSort() && (
                        <span className="ml-1">
                          {header.column.getIsSorted() === "asc" && (
                            <ArrowUp className="h-3.5 w-3.5 text-primary" />
                          )}
                          {header.column.getIsSorted() === "desc" && (
                            <ArrowDown className="h-3.5 w-3.5 text-primary" />
                          )}
                          {!header.column.getIsSorted() && (
                            <ArrowUpDown className="h-3.5 w-3.5 text-muted-foreground/50" />
                          )}
                        </span>
                      )}
                    </div>
                  )}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {table?.getRowModel().rows?.length ? (
            table?.getRowModel().rows.map((row) => {
              const isSelected = row.getIsSelected()
              return (
                <TableRow
                  key={row.id}
                  data-state={isSelected && "selected"}
                  className={cn(
                    "transition-colors duration-150",
                    isSelected && "bg-primary/[0.03] hover:bg-primary/[0.06]"
                  )}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell
                      key={cell.id}
                      className={cn(
                        cell.column.id === "select"
                          ? "sticky left-0 z-10 w-[52px] bg-inherit"
                          : "border-border/40 border-r last:border-r-0"
                      )}
                    >
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              )
            })
          ) : (
            <TableRow>
              <TableCell colSpan={modifiedColumns.length} className="h-32 text-center">
                <div className="flex flex-col items-center gap-2">
                  <div className="h-10 w-10 rounded-full bg-muted flex items-center justify-center">
                    <svg className="h-5 w-5 text-muted-foreground" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2.586a1 1 0 00-.707.293l-2.414 2.414a1 1 0 01-.707.293h-3.172a1 1 0 01-.707-.293l-2.414-2.414A1 1 0 006.586 13H4" />
                    </svg>
                  </div>
                  <p className="text-sm font-medium text-muted-foreground">No results found</p>
                  <p className="text-xs text-muted-foreground/60">Try adjusting your filters</p>
                </div>
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>

      {table?.getRowModel().rows?.length > 0 && pagination && (
        <DataTablePagination
          table={table}
          pageSizeOptions={pagination.pageSizeOptions ?? [10, 20, 30, 40, 50]}
          total_data={pagination?.totalData}
        />
      )}
    </div>
  )
}

"use client"

import { Table } from "@tanstack/react-table"
import BasicPagination from "@/components/datatable/basic-pagination"

interface DataTablePaginationProps<TData> {
  table: Table<TData>
  showSelected?: boolean
  pageSizeOptions?: number[]
  total_data?: number
}

export function DataTablePagination<TData>({
  table,
  showSelected = true,
  pageSizeOptions = [10, 20, 30, 40, 50],
  total_data,
}: DataTablePaginationProps<TData>) {
  const pageIndex = table.getState().pagination.pageIndex
  const pageSize = table.getState().pagination.pageSize
  const currentRows = table.getFilteredRowModel().rows.length

  const startRecord = pageIndex * pageSize + 1
  const endRecord = pageIndex * pageSize + currentRows

  return (
    <div className="flex items-center justify-between px-4 py-3">
      {showSelected && (
        <div className="text-muted-foreground hidden flex-1 text-sm lg:flex">
          Record {startRecord} - {endRecord} of {total_data}
        </div>
      )}
      <div className="hidden items-center gap-2 lg:flex">
        <label htmlFor="rows-per-page" className="text-sm font-medium">
          Rows per page
        </label>
        <select
          id="rows-per-page"
          className="h-8 w-20 rounded-md border border-input bg-background px-2 text-sm focus:outline-none focus:ring-1 focus:ring-ring"
          value={`${table.getState().pagination.pageSize}`}
          onChange={(e) => {
            table.setPageSize(Number(e.target.value))
          }}
        >
          {pageSizeOptions.map((size) => (
            <option key={size} value={`${size}`}>
              {size}
            </option>
          ))}
        </select>
      </div>
      <div className="flex w-full items-center gap-8 lg:ml-4 lg:w-fit">
        <BasicPagination
          totalPages={total_data ? Math.ceil(total_data / table.getState().pagination.pageSize) : 0}
          initialPage={table.getState().pagination.pageIndex + 1}
          onPageChange={(page) => {
            table.setPageIndex(page - 1)
          }}
        />
      </div>
    </div>
  )
}

"use client"

import {
  Pagination,
  PaginationContent,
  PaginationEllipsis,
  PaginationItem,
  PaginationLink,
  PaginationNext,
  PaginationPrevious,
} from "@/components/ui/pagination"
import { cn } from "@/lib/utils"
import { motion } from "framer-motion"
import { ChevronRight } from "lucide-react"
import { useState } from "react"

interface BasicPaginationProps {
  totalPages: number
  initialPage?: number
  siblingsCount?: number
  onPageChange?: (page: number) => void
  className?: string
  variant?: "default" | "outline" | "rounded"
  showDemo?: boolean
}

export default function BasicPagination({
  totalPages = 10,
  initialPage = 1,
  siblingsCount = 1,
  onPageChange,
  className,
  variant = "default",
  showDemo = false,
}: BasicPaginationProps) {
  const [currentPage, setCurrentPage] = useState(initialPage)

  // Generate page numbers array
  const generatePagination = () => {
    // Always show first and last page
    const firstPage = 1
    const lastPage = totalPages

    // Calculate range of pages to show around current page
    const leftSiblingIndex = Math.max(currentPage - siblingsCount, firstPage)
    const rightSiblingIndex = Math.min(currentPage + siblingsCount, lastPage)

    // Determine whether to show ellipses
    const shouldShowLeftDots = leftSiblingIndex > firstPage + 1
    const shouldShowRightDots = rightSiblingIndex < lastPage - 1

    // Initialize the array of page numbers
    const pageNumbers: (number | string)[] = []

    // Always add first page
    pageNumbers.push(firstPage)

    // Add left ellipsis if needed
    if (shouldShowLeftDots) {
      pageNumbers.push("leftEllipsis")
    }

    // Add page numbers between ellipses
    for (let i = leftSiblingIndex; i <= rightSiblingIndex; i++) {
      if (i !== firstPage && i !== lastPage) {
        pageNumbers.push(i)
      }
    }

    // Add right ellipsis if needed
    if (shouldShowRightDots) {
      pageNumbers.push("rightEllipsis")
    }

    // Always add last page if it's not the same as first page
    if (lastPage !== firstPage) {
      pageNumbers.push(lastPage)
    }

    return pageNumbers
  }

  const handlePageChange = (page: number) => {
    if (page === currentPage) return

    setCurrentPage(page)
    onPageChange?.(page)
  }

  const pageNumbers = generatePagination()

  // Variants for motion animations
  const itemVariants = {
    initial: { opacity: 0, y: 5 },
    animate: { opacity: 1, y: 0 },
    exit: { opacity: 0, y: -5 },
    hover: { scale: 1.05, transition: { duration: 0.2 } },
  }

  // Get button style based on variant
  const getButtonStyle = (isActive: boolean) => {
    if (variant === "outline") {
      return isActive
        ? "border-primary text-primary hover:bg-primary/10"
        : "border-border hover:border-primary/50 hover:text-primary"
    }

    if (variant === "rounded") {
      return isActive
        ? "bg-primary text-primary-foreground rounded-full"
        : "hover:bg-muted rounded-full"
    }

    // Default variant
    return isActive ? "bg-primary text-primary-foreground dark:text-primary" : "hover:bg-muted"
  }

  const PaginationComponent = (
    <Pagination className={cn("py-4", className)}>
      <PaginationContent>
        <PaginationItem>
          <motion.div
            initial="initial"
            animate="animate"
            exit="exit"
            whileHover="hover"
            variants={itemVariants}
            transition={{ duration: 0.3 }}
          >
            <PaginationPrevious
              href="#"
              onClick={(e) => {
                e.preventDefault()
                if (currentPage > 1) {
                  handlePageChange(currentPage - 1)
                }
              }}
              className={cn(
                currentPage <= 1 ? "pointer-events-none opacity-50" : "",
                variant === "rounded" ? "rounded-full" : ""
              )}
            />
          </motion.div>
        </PaginationItem>

        {pageNumbers.map((page, index) => {
          if (page === "leftEllipsis" || page === "rightEllipsis") {
            return (
              <PaginationItem key={`ellipsis-${index}`}>
                <motion.div
                  initial="initial"
                  animate="animate"
                  exit="exit"
                  variants={itemVariants}
                  transition={{ duration: 0.3, delay: index * 0.05 }}
                >
                  <PaginationEllipsis />
                </motion.div>
              </PaginationItem>
            )
          }

          const pageNum = page as number
          const isActive = pageNum === currentPage

          return (
            <PaginationItem key={pageNum}>
              <motion.div
                initial="initial"
                animate="animate"
                exit="exit"
                whileHover="hover"
                variants={itemVariants}
                transition={{ duration: 0.3, delay: index * 0.05 }}
              >
                <PaginationLink
                  href="#"
                  isActive={isActive}
                  onClick={(e) => {
                    e.preventDefault()
                    handlePageChange(pageNum)
                  }}
                  className={cn(
                    getButtonStyle(isActive),
                    variant === "outline" && "border",
                    "transition-all duration-200"
                  )}
                >
                  {pageNum}
                </PaginationLink>
              </motion.div>
            </PaginationItem>
          )
        })}

        <PaginationItem>
          <motion.div
            initial="initial"
            animate="animate"
            exit="exit"
            whileHover="hover"
            variants={itemVariants}
            transition={{ duration: 0.3 }}
          >
            <PaginationNext
              href="#"
              onClick={(e) => {
                e.preventDefault()
                if (currentPage < totalPages) {
                  handlePageChange(currentPage + 1)
                }
              }}
              className={cn(
                currentPage >= totalPages ? "pointer-events-none opacity-50" : "",
                variant === "rounded" ? "rounded-full" : ""
              )}
            />
          </motion.div>
        </PaginationItem>
      </PaginationContent>
    </Pagination>
  )

  // If showDemo is true, render the demo with all variants
  if (showDemo) {
    // Sample data for pagination demo
    const demoItems = [
      {
        id: 1,
        title: "Getting Started with MVPBlocks",
        category: "Tutorial",
        date: "Jan 15, 2023",
      },
      {
        id: 2,
        title: "Building Responsive UIs",
        category: "Design",
        date: "Feb 3, 2023",
      },
      {
        id: 3,
        title: "Advanced Animation Techniques",
        category: "Animation",
        date: "Mar 12, 2023",
      },
      {
        id: 4,
        title: "State Management Patterns",
        category: "Development",
        date: "Apr 5, 2023",
      },
      {
        id: 5,
        title: "Optimizing Performance",
        category: "Performance",
        date: "May 20, 2023",
      },
      {
        id: 6,
        title: "Accessibility Best Practices",
        category: "Accessibility",
        date: "Jun 8, 2023",
      },
      {
        id: 7,
        title: "Component Composition",
        category: "Architecture",
        date: "Jul 17, 2023",
      },
      {
        id: 8,
        title: "Testing Strategies",
        category: "Testing",
        date: "Aug 22, 2023",
      },
      {
        id: 9,
        title: "Deployment Workflows",
        category: "DevOps",
        date: "Sep 14, 2023",
      },
      {
        id: 10,
        title: "Theme Customization",
        category: "Design",
        date: "Oct 30, 2023",
      },
      {
        id: 11,
        title: "API Integration Patterns",
        category: "Development",
        date: "Nov 11, 2023",
      },
      {
        id: 12,
        title: "Building Design Systems",
        category: "Design",
        date: "Dec 5, 2023",
      },
      {
        id: 13,
        title: "Mobile-First Approach",
        category: "Design",
        date: "Jan 19, 2024",
      },
      {
        id: 14,
        title: "Server-Side Rendering",
        category: "Performance",
        date: "Feb 8, 2024",
      },
      {
        id: 15,
        title: "Authentication Flows",
        category: "Security",
        date: "Mar 22, 2024",
      },
    ]

    // Items per page
    const itemsPerPage = 3

    // Enhanced pagination component with content
    const EnhancedPagination = ({
      variant = "default",
    }: {
      variant?: "default" | "outline" | "rounded"
    }) => {
      const [page, setPage] = useState(1)

      // Calculate total pages
      const totalPages = Math.ceil(demoItems.length / itemsPerPage)

      // Get current items
      const startIndex = (page - 1) * itemsPerPage
      const currentItems = demoItems.slice(startIndex, startIndex + itemsPerPage)

      return (
        <div className="space-y-6">
          {/* Content area */}
          <motion.div
            className="bg-card/50 rounded-md border p-4"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            key={`page-${page}`} // Key changes force re-animation
            transition={{ duration: 0.3 }}
          >
            <div className="mb-4 flex items-center justify-between border-b pb-2">
              <h4 className="text-muted-foreground text-sm font-medium">
                Showing {startIndex + 1}-{Math.min(startIndex + itemsPerPage, demoItems.length)} of{" "}
                {demoItems.length} items
              </h4>
              <span className="bg-primary/10 text-primary rounded-full px-2 py-1 text-xs font-medium">
                Page {page} of {totalPages}
              </span>
            </div>

            <div className="space-y-4">
              {currentItems.map((item) => (
                <motion.div
                  key={item.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{
                    duration: 0.3,
                    delay: (item.id % itemsPerPage) * 0.1,
                  }}
                  className="hover:bg-muted/50 flex items-center justify-between rounded-md border p-3"
                >
                  <div>
                    <h3 className="font-medium">{item.title}</h3>
                    <div className="text-muted-foreground flex items-center gap-2 text-sm">
                      <span className="bg-primary/10 text-primary rounded-full px-2 py-0.5 text-xs font-medium">
                        {item.category}
                      </span>
                      <span>{item.date}</span>
                    </div>
                  </div>
                  <button className="hover:bg-muted rounded-full p-2">
                    <ChevronRight className="text-muted-foreground h-4 w-4" />
                  </button>
                </motion.div>
              ))}
            </div>
          </motion.div>

          {/* Pagination controls */}
          <Pagination className="py-2">
            <PaginationContent>
              <PaginationItem>
                <motion.div
                  initial="initial"
                  animate="animate"
                  exit="exit"
                  whileHover="hover"
                  variants={itemVariants}
                  transition={{ duration: 0.3 }}
                >
                  <PaginationPrevious
                    href="#"
                    onClick={(e) => {
                      e.preventDefault()
                      if (page > 1) setPage(page - 1)
                    }}
                    className={cn(
                      page <= 1 ? "pointer-events-none opacity-50" : "",
                      variant === "rounded" ? "rounded-full" : ""
                    )}
                  />
                </motion.div>
              </PaginationItem>

              {Array.from({ length: totalPages }).map((_, i) => {
                const pageNum = i + 1
                const isActive = pageNum === page

                // Show ellipsis for many pages
                if (totalPages > 5) {
                  // Always show first and last page
                  if (pageNum === 1 || pageNum === totalPages) {
                    return (
                      <PaginationItem key={pageNum}>
                        <motion.div
                          initial="initial"
                          animate="animate"
                          exit="exit"
                          whileHover="hover"
                          variants={itemVariants}
                          transition={{ duration: 0.3 }}
                        >
                          <PaginationLink
                            href="#"
                            isActive={isActive}
                            onClick={(e) => {
                              e.preventDefault()
                              setPage(pageNum)
                            }}
                            className={cn(
                              getButtonStyle(isActive),
                              variant === "outline" && "border",
                              "transition-all duration-200"
                            )}
                          >
                            {pageNum}
                          </PaginationLink>
                        </motion.div>
                      </PaginationItem>
                    )
                  }

                  // Show current page and adjacent pages
                  if (pageNum === page || pageNum === page - 1 || pageNum === page + 1) {
                    return (
                      <PaginationItem key={pageNum}>
                        <motion.div
                          initial="initial"
                          animate="animate"
                          exit="exit"
                          whileHover="hover"
                          variants={itemVariants}
                          transition={{ duration: 0.3 }}
                        >
                          <PaginationLink
                            href="#"
                            isActive={isActive}
                            onClick={(e) => {
                              e.preventDefault()
                              setPage(pageNum)
                            }}
                            className={cn(
                              getButtonStyle(isActive),
                              variant === "outline" && "border",
                              "transition-all duration-200"
                            )}
                          >
                            {pageNum}
                          </PaginationLink>
                        </motion.div>
                      </PaginationItem>
                    )
                  }

                  // Show ellipsis
                  if (
                    (pageNum === 2 && page > 3) ||
                    (pageNum === totalPages - 1 && page < totalPages - 2)
                  ) {
                    return (
                      <PaginationItem key={`ellipsis-${pageNum}`}>
                        <motion.div
                          initial="initial"
                          animate="animate"
                          exit="exit"
                          variants={itemVariants}
                          transition={{ duration: 0.3 }}
                        >
                          <PaginationEllipsis />
                        </motion.div>
                      </PaginationItem>
                    )
                  }

                  return null
                }

                // Show all pages if total pages <= 5
                return (
                  <PaginationItem key={pageNum}>
                    <motion.div
                      initial="initial"
                      animate="animate"
                      exit="exit"
                      whileHover="hover"
                      variants={itemVariants}
                      transition={{ duration: 0.3 }}
                    >
                      <PaginationLink
                        href="#"
                        isActive={isActive}
                        onClick={(e) => {
                          e.preventDefault()
                          setPage(pageNum)
                        }}
                        className={cn(
                          getButtonStyle(isActive),
                          variant === "outline" && "border",
                          "transition-all duration-200"
                        )}
                      >
                        {pageNum}
                      </PaginationLink>
                    </motion.div>
                  </PaginationItem>
                )
              })}

              <PaginationItem>
                <motion.div
                  initial="initial"
                  animate="animate"
                  exit="exit"
                  whileHover="hover"
                  variants={itemVariants}
                  transition={{ duration: 0.3 }}
                >
                  <PaginationNext
                    href="#"
                    onClick={(e) => {
                      e.preventDefault()
                      if (page < totalPages) setPage(page + 1)
                    }}
                    className={cn(
                      page >= totalPages ? "pointer-events-none opacity-50" : "",
                      variant === "rounded" ? "rounded-full" : ""
                    )}
                  />
                </motion.div>
              </PaginationItem>
            </PaginationContent>
          </Pagination>
        </div>
      )
    }

    return (
      <div className="mx-auto max-w-6xl px-4 py-12">
        <div className="mb-12 text-center">
          <h2 className="mb-2 text-3xl font-bold tracking-tight">Pagination Examples</h2>
          <p className="text-muted-foreground mx-auto max-w-2xl">
            Interactive pagination components that demonstrate real content navigation. Each example
            shows how pagination can be used to navigate through a collection of items.
          </p>
        </div>

        <div className="space-y-16">
          {/* Default Variant */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="bg-card rounded-lg border p-6 shadow-sm"
          >
            <h3 className="mb-6 text-xl font-semibold">Default Style</h3>
            <EnhancedPagination />
          </motion.div>

          {/* Outline Variant */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.1 }}
            className="bg-card rounded-lg border p-6 shadow-sm"
          >
            <h3 className="mb-6 text-xl font-semibold">Outline Style</h3>
            <EnhancedPagination variant="outline" />
          </motion.div>

          {/* Rounded Variant */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
            className="bg-card rounded-lg border p-6 shadow-sm"
          >
            <h3 className="mb-6 text-xl font-semibold">Rounded Style</h3>
            <EnhancedPagination variant="rounded" />
          </motion.div>
        </div>
      </div>
    )
  }

  // Otherwise, just return the pagination component
  return PaginationComponent
}

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { flexRender } from "@tanstack/react-table"

interface SkeletonTableProps {
  columnCount?: number
  rowCount?: number
  table?: any
}

export const SkeletonTable = ({ columnCount = 5, rowCount = 5, table }: SkeletonTableProps) => {
  return (
    <div className="rounded-md border">
      <Table>
        <TableHeader className="bg-muted">
          {table.getHeaderGroups().map((headerGroup: any) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header: any) => (
                <TableHead key={header.id}>
                  {header.isPlaceholder
                    ? null
                    : flexRender(header.column.columnDef.header, header.getContext())}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {Array.from({ length: rowCount }).map((_, rowIndex) => (
            <TableRow key={rowIndex}>
              {Array.from({ length: columnCount }).map((_, colIndex) => (
                <TableCell key={colIndex}>
                  <div className="h-4 w-full animate-pulse rounded bg-gray-200" />
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}
